/**
 * O osso humano — porte de `componentes/viz/osso.js`.
 *
 * Por dentro o osso não é maciço: é uma treliça de trabéculas alinhadas às linhas
 * de força que ele de fato recebe. É o que o torna forte E leve ao mesmo tempo —
 * poucas traves e ele arqueia e racha; muitas e ele vira pedra, forte mas pesada
 * demais para o corpo carregar.
 *
 * A cena deforma o osso conforme ele enfraquece: o arqueamento sob a carga é a
 * parte que se entende sem ler nada.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import { type EstadoDaViz, infoDe, limitar, numeroDe, paleta, texto, titulo } from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** Abaixo disto o osso é frágil — espelha o `alvoMin` do renderizador. */
const FRAGIL = 45;

const osso: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const densidade = Math.max(0, numeroDe(valores, 'd', 0));
    const ok = info.ok === true;
    const fragil = densidade < FRAGIL;
    const forcaPorPeso = numeroDe(info, 'fpp', 0);

    const tinta = ok ? cor.verde : fragil ? cor.erro : cor.ouro;
    const corpo = ok ? '#d8f0e0' : fragil ? '#f0d2d4' : '#efe2c4';

    titulo(ctx, L, A, 'Forte e leve ao mesmo tempo');

    const cx = L / 2;
    const topo = A * 0.24;
    const fim = A * 0.84;
    const larg = L * 0.13;
    const H = fim - topo;

    // O arqueamento é proporcional à fragilidade — é ele que conta a história.
    const carga = fragil ? 1 - densidade / FRAGIL : 0;
    const flexao = carga * larg * 1.4;
    const achatamento = carga * 0.05;

    const arco = (u: number): number => Math.sin(u * Math.PI) * flexao;
    const yEm = (u: number): number => topo + (H * achatamento) / 2 + u * H * (1 - achatamento);
    const meiaLargura = (u: number): number => {
      const extremo = Math.max(0, 1 - Math.min(u, 1 - u) / 0.14);
      return larg * 0.52 + larg * 0.5 * extremo;
    };

    // A carga que ele sustenta.
    ctx.fillStyle = cor.fraco;
    ctx.fillRect(cx - L * 0.17, topo - 24, L * 0.34, 14);
    texto(ctx, 'carga', cx, topo - 32, limitar(A * 0.034, 8, 11), { cor: cor.fraco, peso: 700 });

    // As epífises — as cabeças que dão a silhueta de osso longo.
    const raioCabeca = larg * 0.66;
    const cabecas = (yc: number, xc: number): void => {
      ctx.fillStyle = corpo;
      for (const lado of [-1, 1]) {
        ctx.beginPath();
        ctx.arc(xc + lado * larg * 0.52, yc, raioCabeca, 0, Math.PI * 2);
        ctx.fill();
      }
    };
    cabecas(topo + raioCabeca * 0.5, cx + arco(0));
    cabecas(fim - raioCabeca * 0.5, cx + arco(1));

    // A diáfise.
    const N = 40;
    const esquerda: [number, number][] = [];
    const direita: [number, number][] = [];
    for (let i = 0; i <= N; i++) {
      const u = i / N;
      const x = cx + arco(u);
      const y = yEm(u);
      const hw = meiaLargura(u);
      esquerda.push([x - hw, y]);
      direita.push([x + hw, y]);
    }

    const contorno = (): void => {
      const primeiro = esquerda[0] ?? [0, 0];
      ctx.beginPath();
      ctx.moveTo(primeiro[0], primeiro[1]);
      for (const p of esquerda) ctx.lineTo(p[0], p[1]);
      for (let i = direita.length - 1; i >= 0; i--) {
        const p = direita[i] ?? [0, 0];
        ctx.lineTo(p[0], p[1]);
      }
      ctx.closePath();
    };

    contorno();
    ctx.fillStyle = corpo;
    ctx.fill();
    ctx.strokeStyle = tinta;
    ctx.lineWidth = 3;
    ctx.stroke();

    // As trabéculas, recortadas dentro da haste.
    ctx.save();
    contorno();
    ctx.clip();

    const traves = Math.round(2 + (densidade / 100) * 22);
    const passo = H / Math.max(1, traves);
    ctx.strokeStyle = ok ? cor.verde : fragil ? cor.erro : cor.ouro;
    ctx.globalAlpha = 0.7;
    ctx.lineWidth = 1.4;
    for (let i = -traves; i <= traves; i++) {
      const y = topo + i * passo;
      const u0 = limitar((y - topo) / H, 0, 1);
      const u1 = limitar((y + larg * 2 - topo) / H, 0, 1);
      const xa = cx + arco(u0);
      const xb = cx + arco(u1);

      ctx.beginPath();
      ctx.moveTo(xa - larg, y);
      ctx.lineTo(xb + larg, y + larg * 2);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(xb + larg, y);
      ctx.lineTo(xa - larg, y + larg * 2);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
    ctx.restore();

    // A rachadura nasce no flanco interno do arco, onde a tração se concentra.
    if (fragil) {
      const yc = yEm(0.5);
      const xc = cx + arco(0.5);
      ctx.strokeStyle = cor.erro;
      ctx.lineWidth = 2.5;
      ctx.lineJoin = 'round';
      ctx.beginPath();
      ctx.moveTo(xc - meiaLargura(0.5), yc - larg * 0.5);
      ctx.lineTo(xc - larg * 0.1, yc - larg * 0.2);
      ctx.lineTo(xc + larg * 0.3, yc + larg * 0.4);
      ctx.lineTo(xc + meiaLargura(0.5) * 0.4, yc + larg * 0.2);
      ctx.stroke();
    }

    texto(
      ctx,
      `Força por peso: ${Math.round(forcaPorPeso)}%${
        ok ? ' — forte e leve ✔' : fragil ? ' — arqueia e racha' : ''
      }`,
      cx,
      A * 0.95,
      limitar(A * 0.044, 10, 14),
      { cor: ok ? cor.verde : cor.fraco, peso: 700 },
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A }) => desenhar(ctx, L, A),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default osso;
